static void smarttvsystem_eventqueue_init(smarttvsystem_eventqueue * eq, smarttvsystem_event *buffer, sc_integer capacity)
{
	eq->events = buffer;
	eq->capacity = capacity;
	eq->push_index = 0;
	eq->pop_index = 0;
	eq->size = 0;
}

static sc_integer smarttvsystem_eventqueue_size(smarttvsystem_eventqueue * eq)
{
	return eq->size;
}

static smarttvsystem_event smarttvsystem_eventqueue_pop(smarttvsystem_eventqueue * eq)
{
	smarttvsystem_event event;
	if(smarttvsystem_eventqueue_size(eq) <= 0) {
		smarttvsystem_event_init(&event, SmartTVSystem_invalid_event);
	}
	else {
		event = eq->events[eq->pop_index];
		
		if(eq->pop_index < eq->capacity - 1) {
			eq->pop_index++;
		} 
		else {
			eq->pop_index = 0;
		}
		eq->size--;
	}
	return event;
}
static sc_boolean smarttvsystem_eventqueue_push(smarttvsystem_eventqueue * eq, smarttvsystem_event ev)
{
	if(smarttvsystem_eventqueue_size(eq) == eq->capacity) {
		return bool_false;
	}
	else {
		eq->events[eq->push_index] = ev;
		
		if(eq->push_index < eq->capacity - 1) {
			eq->push_index++;
		}
		else {
			eq->push_index = 0;
		}
		eq->size++;
		
		return bool_true;
	}
}
static void smarttvsystem_event_init(smarttvsystem_event * ev, SmartTVSystemEventID name)
{
	ev->name = name;
}

static void smartTVSystem_add_event_to_queue(smarttvsystem_eventqueue * eq, SmartTVSystemEventID name)
{
	smarttvsystem_event event;
	smarttvsystem_event_init(&event, name);
	smarttvsystem_eventqueue_push(eq, event);
}

