static smarttvsystem_event smartTVSystem_get_next_event(SmartTVSystem* handle)
{
	smarttvsystem_event next_event;
	smarttvsystem_event_init(&next_event, SmartTVSystem_invalid_event);
	if(smarttvsystem_eventqueue_size(&(handle->in_event_queue)) > 0) {
		next_event = smarttvsystem_eventqueue_pop(&(handle->in_event_queue));
	}
	return next_event;
}

static sc_boolean smartTVSystem_dispatch_next_event(SmartTVSystem* handle)
{
	smarttvsystem_event nextEvent;
	nextEvent = smartTVSystem_get_next_event(handle);
	return smartTVSystem_dispatch_event(handle, &nextEvent);
}

